/*
 * A267766  Numbers whose base-6 representation is a square when read in base
 *          10.
 * https://oeis.org/A267766
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 12, u16 n <= 116, u32 n <= 7103, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   seq_alloc, seq_realloc, square_to_seq
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* A267766: numbers whose base‑6 representation is a square when read in base‑10. */
/* The sequence is generated by scanning squares k², keeping those whose
   decimal digits are all ≤5, interpreting that decimal string as a base‑6
   number, and storing the results in increasing order. */

#include <stddef.h>
#include <stdbool.h>
#include <stdint.h>
#include "../utils/seq_alloc.h"
#include "../utils/seq_realloc.h"
#include "../utils/square_to_seq.h"

/* Cached sequence storage (static state). */
static seq_t *cached_seq  = NULL; /* pointer to array of values */
static size_t cached_len  = 0;     /* number of terms stored */
static size_t cached_cap  = 0;     /* allocated capacity */
static idx_t  next_k      = 0;     /* next integer k to test */

seq_t a(idx_t n)
{
    if (n == 0) return 0;                 /* safety for an offset of 1 */

    /* lazily allocate the cache */
    if (cached_seq == NULL) {
        cached_cap = 16;
        cached_seq = seq_alloc(cached_cap);
        cached_len = 0;
    }

    /* extend the cache until it holds at least n terms */
    while (cached_len < (size_t)n) {
        idx_t k   = next_k++;            /* next integer to square */
        idx_t sq  = k * k;               /* square, fits in idx_t */

        seq_t val;
        if (square_to_seq(sq, &val)) {
            /* resize if necessary */
            if (cached_len == cached_cap) {
                size_t new_cap = cached_cap * 2;
                seq_t *newp    = seq_realloc(cached_seq, cached_cap, new_cap);
                cached_seq     = newp;
                cached_cap     = new_cap;
            }
            cached_seq[cached_len++] = val;
        }
    }

    return cached_seq[n - 1];
}
